local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local MAXSKILLNUM = 6   --最大的节能数量
local UICommonHpAndEnergyNode = "Game.UI.FightTeam.UICommonHpAndEnergyNode"

---@type UIBattlingTools
local UIBattlingTools = import("Game.UI.UIBattling.UIBattlingTools")

---@class CommonMonstCardNode
local CommonMonstCardNode = Class("CommonMonstCardNode")

function CommonMonstCardNode:__init() 
    self._uiCommonHpAndEnergyNodeScr = nil
end

function CommonMonstCardNode:__delete()
    self._uiCommonHpAndEnergyNodeScr = nil
end

function CommonMonstCardNode:Awake()
    self.controller.ClearCache = false
end

--刷新信息
function CommonMonstCardNode:RefeshInfo(monstId, hpEnergydata, level, attr)
    if not monstId then
        return
    end

    local npcVo = CardConfMgr:GetInstance():GetMonsterTypeVoById(monstId)
    if not npcVo then return end
    CfUtils.FillImage(self.Head, CardConfMgr:GetInstance():GetMonstHeadIcon(monstId))
    CfUtils.FillImage(self.Bg, CardConfMgr:GetInstance():GetMonstHeadBg(monstId))   

    --这是卡牌怪物
    if npcVo.role > 0 then
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(npcVo.mode)
        if cardVo then
            --属性如果指定  强制替换
            if checkNumber(attr) > 0 then
                CfUtils.FillImage(self.AttrImg, CardUtils.GetGoodsCardAttrIconByCardAttrType(attr))
            else
                CfUtils.FillImage(self.AttrImg, CardUtils.GetGoodsCardAttrIconByCardAttrType(cardVo.attributeType))
            end
        end
    else
        if checkNumber(attr) > 0 then
            CfUtils.FillImage(self.AttrImg, UICommonUtils.GetMonsterAttributeIcon(attr))
        else
            CfUtils.FillImage(self.AttrImg, UICommonUtils.GetMonsterAttributeIcon(npcVo.attribute))
        end
    end

    --等级
    if checkNumber(level) > 0 then
        CfUtils.FillText(self.Level, level)
    else
        KTool.SetActive(self.Level, false)
        KTool.SetActive(self.NameBg, false)
    end

    self:FillHpEenergyData(hpEnergydata)
end

function CommonMonstCardNode:SetLevelActive(isTrue)
    KTool.SetActive(self.Level, isTrue)
    KTool.SetActive(self.NameBg, isTrue)
end

--绘制血量信息
function CommonMonstCardNode:FillHpEenergyData(data)
    if not data then
        return
    end

    KTool.SetActive(self.HpEnergyNode, true)
    if not self._uiCommonHpAndEnergyNodeScr then
        self._uiCommonHpAndEnergyNodeScr = CfUtils.GetLuaScr(self.CommonHpEnergyNode, UICommonHpAndEnergyNode)
    end
    self._uiCommonHpAndEnergyNodeScr:Refresh(data)
end

--只绘制一个头像
function CommonMonstCardNode:RefeshMonstHeadIcon(data, go)
    if not data then
        return 
    end
    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(data.skinId)
    if skinVo then 
        CfUtils.FillImage(self.Head, skinVo.buffHead)
    end
    --CfUtils.FillImage(self.ImgIcon, data.cardHeadPath)

    local titles = {}
    local descs = {}
    for i = 1, MAXSKILLNUM do
        local num = (i == 1 and "" or i)

        local skillCardId = data["atkSkill"..num]
        if checkNumber(skillCardId) > 0 then
            ---@type SkillCardVo
            local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillCardId)
            --怪物只取1星的
            if skillCardVo then
               table.insert(descs, skillCardVo.skillName)
               table.insert(titles, table.concat(CardUtils.ParseSkillDescBySkillId(skillCardId, 1)))
            end
        end
    end
    local skillCardId = data["hitSkill"]
    ---@type SkillCardVo
    local skillCardVo = UIBattlingTools.GetSkillCardInfoByTwoParam(skillCardId)
    if skillCardVo then
        table.insert(descs, skillCardVo.skillName)
        table.insert(titles, table.concat(CardUtils.ParseSkillDescBySkillId(skillCardId, 1)))
    end

    CfUtils.FillImage(self.AttrImg, UICommonUtils.GetMonsterAttributeIcon(data.attribute))

    SetButtonAction(go, function()
        GameUtils.ShowCommonTipsBoardSecond(self.Head, localize("召唤物"), titles, nil, nil, false, descs)
    end)

    self:SetLevelActive(false)
    KTool.SetActive(self.EnemyInfo.transform:Find("LV"), false)
end

function CommonMonstCardNode:OnDestroy()
    ---加回到对象池中去
    self:Delete()
    self.controller = nil--luabehaviour 中CSharp对象
    self = nil
end

return CommonMonstCardNode
